function createUserProfile(name, age, email, isActive) {
  const profile = {
    name,
    age,
    email,
    isActive,
    createdAt: new Date().toISOString()
  };
  return profile;
}

function reportTypes(value) {
  const type = typeof value;
  return `The value "${value}" is of type: ${type}`;
}

const user = createUserProfile("Alice", 30, "alice@example.com", true);
console.log(reportTypes(user.name));
console.log(reportTypes(user.age));
console.log(reportTypes(user.isActive));
console.log(reportTypes(user));
